-import { PanelDownloadDialog } from '@/components/dialog/panel-download-dialog';
-
-import { ToolbarDropdownItem } from './toolbar-dropdown-item';
-
-/**
- * Download dropdown component for the canvas toolbar.
- *
- * Provides three download options:
- * 1. Download Image - Direct download of the selected image
- * 2. Download Panel - Opens PanelDownloadDialog with export settings
- * 3. Download Canvas - Opens existing canvas export dialog
- *
- * Selection-aware: Options are enabled/disabled based on current selection state.
- */
-const CanvasDownloadDropdown = () => {
-  const t = useTranslations('Canvas.toolbar.download');
-  const tCanvas = useTranslations('Canvas');
-  const { openCanvasExportDialog, isCanvasExporting } = useCanvasExport();
-  const isLoaded = useCanvasStore((state) => state.isLoaded);
-  const { downloadOptions, selectedImage, selectedPanel } =
-    useSelectionAwareOptions();
-  const { canvasObjects } = useHistoryState();
-
-  // Panel download dialog state
-  const [isPanelDialogOpen, setIsPanelDialogOpen] = useState(false);
-
-  // Find the option states
-  const imageOption = downloadOptions.find((opt) => opt.id === 'image');
-  const panelOption = downloadOptions.find((opt) => opt.id === 'panel');
-  const canvasOption = downloadOptions.find((opt) => opt.id === 'canvas');
-
-  const handleDownloadImage = async () => {
-    if (!selectedImage) {
-      toast.error(t('selectImageFirst'));
-      return;
-    }
-
-    // Get the image source
-    const src = Array.isArray(selectedImage.src)
-      ? selectedImage.src[selectedImage.currentIndex ?? 0] ??
-        selectedImage.src[0]
-      : selectedImage.src;
-
-    if (!src) {
-      toast.error(tCanvas('actionsInfo.download.noImageSelected'));
-      return;
-    }
-
-    // Generate filename
-    const filename = `image-${selectedImage.id.slice(0, 8)}.png`;
-
-    // Trigger direct download (no watermark for canvas)
-    triggerDownload(src, filename);
-    toast.success(tCanvas('actionsInfo.download.imageDownloadedSuccessfully'));
-
-    mixpanel.track('[Canvas] Image Download', {
-      source: 'toolbar_dropdown',
-      imageId: selectedImage.id
-    });
-  };
-
-  const handleDownloadPanel = () => {
-    if (!selectedPanel) {
-      toast.error(t('selectPanelFirst'));
-      return;
-    }
-
-    // Open the panel download dialog
-    setIsPanelDialogOpen(true);
-
-    mixpanel.track('[Canvas] Panel Download Dialog Opened', {
-      source: 'toolbar_dropdown',
-      panelId: selectedPanel.id
-    });
-  };
-
-  const handleDownloadCanvas = () => {
-    openCanvasExportDialog();
-
-    mixpanel.track('[Canvas] Canvas Download', {
-      source: 'toolbar_dropdown'
-    });
-  };
-
-  return (
-    <>
-      <DropdownMenu>
-        <DropdownMenuTrigger asChild>
-          <button
-            data-testid="canvas-download-dropdown"
-            className="relative p-1 rounded-lg transition-colors min-h-[44px] min-w-[44px] flex items-center justify-center touch-manipulation hover:bg-gray-100 hover:text-blue-600 disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:bg-transparent"
-            disabled={isCanvasExporting || !isLoaded}
-            title={t('title')}
-          >
-            {isCanvasExporting && (
-              <Spinner
-                size={12}
-                className="absolute top-1 right-1 z-10 bg-blue-400 rounded-full text-white p-[1px]"
-              />
-            )}
-            <Download size={20} />
-            <span className="sr-only">{t('title')}</span>
-          </button>
-        </DropdownMenuTrigger>
-        <DropdownMenuContent align="end" side="top" className="w-56">
-          <ToolbarDropdownItem
-            icon={ImageIcon}
-            label={t('image')}
-            enabled={imageOption?.enabled ?? false}
-            disabledHint={imageOption?.disabledReason}
-            onClick={handleDownloadImage}
-          />
-          <ToolbarDropdownItem
-            icon={PanelTop}
-            label={t('panel')}
-            enabled={panelOption?.enabled ?? false}
-            disabledHint={panelOption?.disabledReason}
-            onClick={handleDownloadPanel}
-          />
-          <ToolbarDropdownItem
-            icon={Layout}
-            label={t('canvas')}
-            enabled={canvasOption?.enabled ?? true}
-            disabledHint={canvasOption?.disabledReason}
-            onClick={handleDownloadCanvas}
-          />
-        </DropdownMenuContent>
-      </DropdownMenu>
-
-      {/* Panel Download Dialog */}
-      <PanelDownloadDialog
-        open={isPanelDialogOpen}
-        onOpenChange={setIsPanelDialogOpen}
-        panel={selectedPanel}
-        canvasObjects={canvasObjects}
-      />
-    </>
-  );
-};
-
-export default CanvasDownloadDropdown;
