diff --git a/components/canvas/canvas-image-publish-dialog.tsx b/components/canvas/canvas-image-publish-dialog.tsx
new file mode 100644
index 0000000..91b1489
--- /dev/null
+++ b/components/canvas/canvas-image-publish-dialog.tsx
@@ -0,0 +1,312 @@
+'use client';
+
+import {
+  useState,
+  useTransition,
+  useRef,
+  useCallback,
+  useEffect,
+  useMemo
+} from 'react';
+import { useTranslations, useLocale } from 'next-intl';
+import { useForm } from 'react-hook-form';
+import { zodResolver } from '@hookform/resolvers/zod';
+import { useToggle } from '@uidotdev/usehooks';
+import mixpanel from 'mixpanel-browser';
+import { Artwork, Image as ImageType } from '@prisma/client';
+import Image from 'next/image';
+import { toast } from 'sonner';
+
+import PublishDialog from '@/components/dialog/publish-dialog';
+import ShareDialog from '@/components/dialog/share-dialog';
+import { PublishArtworkFormValues, PublishArtworkSchema } from '@/schemas';
+import { createArtwork, generateArtworkDetails } from '@/actions/artwork';
+import { createArtworkAccessToken } from '@/actions/artwork-token';
+import { isSimpleCanvasModeEnabled } from '@/lib/feature-flags';
+import { GAZAI_RECOMMENDATION_TAG } from '@/constants';
+import { validateImageNsfw } from '@/utils/canvas/nsfw-validation';
+import useIsBanned from '@/hooks/use-is-banned';
+import { useSelectionAwareOptions } from '@/hooks/use-selection-aware-options';
+import { useImagePublishStore } from '@/store/canvas/image-publish-store';
+import Spinner from '@/components/spinner';
+import {
+  AlertDialog,
+  AlertDialogFooter,
+  AlertDialogDescription,
+  AlertDialogContent,
+  AlertDialogHeader,
+  AlertDialogTitle,
+  AlertDialogAction
+} from '@/components/ui/alert-dialog';
+
+const IS_SIMPLE_CANVAS_MODE = isSimpleCanvasModeEnabled();
+
+/**
+ * Renders the single-image publish dialog for Canvas.
+ * Listens to publishRequestCount (e.g. from FloatingQuickActions "Publish" button);
+ * when it increments, opens the dialog for the currently selected image.
+ * Does not handle panel or canvas (webtoon) publish.
+ */
+export default function CanvasImagePublishDialog() {
+  const t = useTranslations('Canvas.toolbar.publish');
+  const tGeneral = useTranslations();
+  const tCanvas = useTranslations('Canvas');
+  const tError = useTranslations('errors');
+  const locale = useLocale();
+
+  const { selectedImage } = useSelectionAwareOptions();
+  const { isBanned, releaseAt } = useIsBanned();
+
+  const [isPending, startTransition] = useTransition();
+  const [privatePublish, setPrivatePublish] = useState(false);
+  const [isPublishDialogOpen, onTogglePublishDialog] = useToggle(false);
+  const [nsfwDialogOpen, toggleNsfwDialog] = useToggle(false);
+  const [imageNsfwWords, setImageNsfwWords] = useState<string[]>([]);
+  const [isShareDialogOpen, onToggleShareDialog] = useToggle(false);
+  const [publishedArtwork, setPublishedArtwork] = useState<
+    (Artwork & { image: (ImageType & { url: string }) | null }) | null
+  >(null);
+  const [accessToken, setAccessToken] = useState<string | null>(null);
+  const [isGeneratingDetails, setIsGeneratingDetails] = useState(false);
+  const hasAutoFilledImage = useRef(false);
+
+  const publishRequestCount = useImagePublishStore(
+    (state) => state.publishRequestCount
+  );
+  const publishRequestCountRef = useRef(publishRequestCount);
+
+  const form = useForm<PublishArtworkFormValues>({
+    resolver: zodResolver(PublishArtworkSchema),
+    defaultValues: { name: '', description: '', tags: [] }
+  });
+
+  const checkBanned = useCallback((): boolean => {
+    if (isBanned) {
+      toast.error(tError('userBanned', { releaseAt }));
+      return true;
+    }
+    return false;
+  }, [isBanned, releaseAt, tError]);
+
+  const handlePublishImage = useCallback(() => {
+    if (checkBanned()) return;
+    if (!selectedImage) {
+      toast.error(t('selectImageFirst'));
+      return;
+    }
+    const validation = validateImageNsfw(selectedImage);
+    if (validation.isBlocked) {
+      setImageNsfwWords(validation.nsfwWords);
+      toggleNsfwDialog();
+      return;
+    }
+    onTogglePublishDialog(true);
+    mixpanel.track('[Canvas] Image Publish Dialog Opened', {
+      source: 'quick_actions',
+      imageId: selectedImage.id
+    });
+  }, [
+    checkBanned,
+    selectedImage,
+    t,
+    toggleNsfwDialog,
+    onTogglePublishDialog
+  ]);
+
+  // React to publish request from FloatingQuickActions (or other callers)
+  useEffect(() => {
+    if (publishRequestCountRef.current === publishRequestCount) return;
+    publishRequestCountRef.current = publishRequestCount;
+    handlePublishImage();
+  }, [publishRequestCount, handlePublishImage]);
+
+  // Auto-fill form when dialog opens (once per open)
+  useEffect(() => {
+    if (!isPublishDialogOpen || !selectedImage || hasAutoFilledImage.current)
+      return;
+
+    const autoFillForm = async () => {
+      try {
+        hasAutoFilledImage.current = true;
+        setIsGeneratingDetails(true);
+
+        const imageId =
+          selectedImage.imageIds?.[selectedImage.currentIndex ?? 0] ||
+          selectedImage.imageIds?.[0] ||
+          selectedImage.imageId ||
+          null;
+
+        if (!imageId) {
+          setIsGeneratingDetails(false);
+          return;
+        }
+
+        const userPrompt = selectedImage.userPrompt;
+        const details = await generateArtworkDetails(
+          imageId,
+          locale,
+          userPrompt
+        );
+
+        if (details.name || details.description || details.tags.length > 0) {
+          form.setValue('name', details.name || '');
+          if (details.description) {
+            form.setValue('description', details.description);
+          }
+          if (details.tags.length > 0) {
+            form.setValue('tags', details.tags);
+          }
+        }
+      } catch {
+        // Silently fail; leave form empty
+      } finally {
+        setIsGeneratingDetails(false);
+      }
+    };
+
+    autoFillForm();
+  }, [isPublishDialogOpen, selectedImage, locale, form]);
+
+  const onPublish = useCallback(
+    (values: PublishArtworkFormValues) => {
+      if (!selectedImage) return;
+
+      startTransition(async () => {
+        const imageId =
+          selectedImage.imageIds?.[0] || selectedImage.imageId || '';
+
+        const baseTags = IS_SIMPLE_CANVAS_MODE
+          ? ['canvas', GAZAI_RECOMMENDATION_TAG]
+          : ['canvas'];
+        const allTags = values.tags
+          ? [...baseTags, ...values.tags.filter((t) => !baseTags.includes(t))]
+          : baseTags;
+
+        const payload = {
+          name: values.name,
+          description: values.description,
+          isPublic: !privatePublish,
+          isNsfw: false,
+          imageGenerationId: selectedImage.imageGenerationId,
+          imageId,
+          editedImageId: imageId,
+          tags: allTags
+        };
+
+        try {
+          const artwork = await createArtwork(payload);
+          if (privatePublish) {
+            const token = await createArtworkAccessToken({
+              artworkId: artwork.id
+            });
+            setAccessToken(token.token);
+          } else {
+            setAccessToken(null);
+          }
+          setPublishedArtwork(artwork);
+          onToggleShareDialog();
+        } catch (error) {
+          console.error('Failed to publish image:', error);
+          toast.error(tCanvas('webtoon.publishDialog.error.publishFailed'));
+        } finally {
+          mixpanel.track('[Canvas] Image published', {
+            artwork_name: values.name,
+            artwork_tags: values.tags,
+            artwork_description: values.description,
+            imageGenerationId: selectedImage.imageGenerationId,
+            imageId
+          });
+          onTogglePublishDialog(false);
+          form.reset();
+        }
+      });
+    },
+    [
+      selectedImage,
+      privatePublish,
+      onToggleShareDialog,
+      onTogglePublishDialog,
+      form,
+      tCanvas
+    ]
+  );
+
+  const handleTogglePublishDialog = useCallback(
+    (open: boolean) => {
+      if (open && checkBanned()) return;
+      onTogglePublishDialog(open);
+      if (!open) {
+        form.reset();
+        setIsGeneratingDetails(false);
